const keys = ['Job title', 'Company', 'Company industry', 'Company employees', 'Company location', 'Company description'];
const lead = keys.map(k => `${k}: ${$json[k] || 'unknown'}`).join('
');
return { ...$json, decisionInput: `Ideal customer profile:
${$('Your settings').first().json.icp}

Lead:
${lead}` };

